    "usageCode": "import { IsometricCity } from \"@/components/ui/IsometricCity\";\n\nexport function Example() {\n  return (\n    <IsometricCity\n      gridSize={7}\n      buildingDensity={0.8}\n      trafficSpeed={1.0}\n      colorPalette=\"midnight\"\n      windowFlicker\n    />\n  );\n}",
    "cliCommand": "npx shadcn@latest add https://boseui.site/r/isometric-city.json",
