    "usageCode": "import { StoryCards } from \"@/components/ui/StoryCards\";\n\nexport function Example() {\n  return (\n    <div className=\"w-full max-w-5xl mx-auto p-4\">\n      <StoryCards\n        title=\"Featured Stories\"\n        subtitle=\"Swipe or scroll to explore latest releases.\"\n        autoPlay={false}\n      />\n    </div>\n  );\n}",
