    "usageCode": "import { WarpSpeed } from \"@/components/ui/warp-speed\";\n\nexport function Example() {\n  return (\n    <WarpSpeed\n      speed={180}\n      starCount={320}\n      streakLength={1.4}\n      followCursor\n    />\n  );\n}",
    "cliCommand": "npx shadcn@latest add https://boseui.site/r/warp-speed.json",
