    "usageCode": "import { WeatherCard } from \"@/components/ui/weather-card\";\n\nexport function WeatherDemo() {\n  return (\n    <div className=\"flex items-center justify-center p-6 bg-black min-h-[500px]\">\n      <WeatherCard location=\"San Francisco, CA\" />\n    </div>\n  );\n}",
